import {enhanceKnob,bindMixGesture,syncKnob} from './studio-console.js';
import {getInstrument,notesFor,noteName,audibleTracks,barBeats} from './catalog.js';
import {ART} from './instrument-art.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=n=>Math.round(n*100)+'%';
const pan=n=>Math.abs(n)<.01?'Center':Math.round(Math.abs(n)*100)+(n<0?' L':' R');
const meter=id=>`<div class="console-meter" role="meter" aria-label="${esc(id==='master'?'Master':id)} signal level" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0" data-meter="${esc(id)}"><i></i></div>`;
function range(id,prop,label,value,min=0,max=1,vertical=false){return `<label class="console-control ${vertical?'console-fader':prop==='pan'?'console-pan-knob':''}"><span>${label}</span>${prop==='pan'?'<span class="hardware-knob">':''}<input aria-label="${esc(label+' · '+id)}" type="range" min="${min}" max="${max}" step=".01" value="${value}" data-mix-id="${id}" data-mix-prop="${prop}" ${prop==='pan'?'data-pan':''}>${prop==='pan'?'</span>':''}<output>${prop==='pan'?pan(value):prop==='reverbDecay'?value.toFixed(1)+' s':pct(value)}</output></label>`}
export function renderConsole(container,p,view,{artwork,checkpoint,change,open}){
 const mixer=view==='mixer';
 container.innerHTML=`<div class="view-header"><div><div class="eyebrow">${mixer?'THE MIXING DESK':'FOLLOW THE MUSIC'}</div><h1>${mixer?'Ensemble mixer':'Ensemble view'}</h1><p>${mixer?'Balance every part. Place each voice. Give the ensemble room.':'One instrument picture per part. Only its own notes light up.'}</p></div><button class="outline" data-view="${mixer?'ensemble':'mixer'}">${mixer?'Ensemble view':'Open mixer'} ↗</button></div>`;
 if(!p.tracks.length){container.insertAdjacentHTML('beforeend','<div class="empty-state"><p>Add instruments to your ensemble to see them here.</p><button class="brass" data-view="library">Choose instruments</button></div>');return;}
 if(mixer){container.insertAdjacentHTML('beforeend',`<div class="mix-master"><div><div class="eyebrow">MASTER BUS</div><h2>The whole ensemble</h2>${meter('master')}</div>${range('master','master','Level',p.master)}${range('master','reverb','Reverb return',p.reverb)}<label class="console-control"><span>Space</span><select id="mix-room" aria-label="Reverb space"><option value=".7">Studio · 0.7 s</option><option value="2.4">Room · 2.4 s</option><option value="4.5">Concert hall · 4.5 s</option><option value="7">Cathedral · 7 s</option><option value="custom">Custom</option></select></label>${range('master','reverbDecay','Decay',p.reverbDecay??2.4,.3,8)}${range('master','delay','Delay',p.delay)}</div><p class="mix-caption">Sends follow each part’s level and pan. Your mix is saved with the project and used for WAV and MP3 exports.</p><div class="mix-channels">${p.tracks.map((t,i)=>`<article class="mix-channel" data-channel="${t.id}"><span class="channel-number">${String(i+1).padStart(2,'0')}</span><button class="mix-art ${getInstrument(t.instrument).shape==='recorder'?'is-recorder':''}" data-console-open="${t.id}" aria-label="Open ${esc(t.name)}">${artwork(getInstrument(t.instrument))}</button><h2>${esc(t.name)}</h2><div class="mix-switches"><button data-mix-toggle="muted" data-mix-id="${t.id}" aria-pressed="${!!t.muted}">Mute</button><button data-mix-toggle="solo" data-mix-id="${t.id}" aria-pressed="${!!t.solo}">Solo</button></div>${range(t.id,'pan','Pan',t.pan,-1,1)}<div class="fader-well">${range(t.id,'volume','Level',t.volume,0,1,true)}${meter(t.id)}</div>${range(t.id,'reverbSend','Reverb send',t.reverbSend??1)}</article>`).join('')}</div>`);
 const select=container.querySelector('#mix-room');const syncRoom=()=>select.value=[.7,2.4,4.5,7].includes(p.reverbDecay??2.4)?String(p.reverbDecay??2.4)==='0.7'?'.7':String(p.reverbDecay??2.4):'custom';syncRoom();select.onchange=()=>{if(select.value==='custom')return;checkpoint();p.reverbDecay=Number(select.value);const input=container.querySelector('[data-mix-prop="reverbDecay"]');input.value=p.reverbDecay;input.nextElementSibling.textContent=p.reverbDecay.toFixed(1)+' s';change();};
 container.querySelectorAll('input[data-mix-prop]').forEach(el=>{bindMixGesture(el,checkpoint);el.oninput=()=>{const target=el.dataset.mixId==='master'?p:p.tracks.find(t=>t.id===el.dataset.mixId),prop=el.dataset.mixProp;target[prop]=Number(el.value);el.closest('label').querySelector('output').textContent=prop==='pan'?pan(target[prop]):prop==='reverbDecay'?target[prop].toFixed(1)+' s':pct(target[prop]);if(prop==='reverbDecay')syncRoom();change()};if(el.dataset.mixProp==='pan')enhanceKnob(el);});
 container.querySelectorAll('[data-mix-toggle]').forEach(el=>el.onclick=()=>{checkpoint();const t=p.tracks.find(t=>t.id===el.dataset.mixId),prop=el.dataset.mixToggle;t[prop]=!t[prop];el.setAttribute('aria-pressed',t[prop]);change()});
 }else{
 container.insertAdjacentHTML('beforeend',`<div class="ensemble-clock"><strong id="ensemble-section">Ready to play</strong><span id="ensemble-count">Measure 1 · Beat 1</span><div class="ensemble-beats">${Array.from({length:p.meter==='6/8'?6:barBeats(p)},(_,i)=>`<i data-beat-dot="${i}"></i>`).join('')}</div><small>Upcoming notes · next 4 beats →</small></div><div class="ensemble-grid">${p.tracks.map(t=>`<button class="ensemble-tile ${getInstrument(t.instrument).shape==='recorder'?'is-recorder':''}" data-console-open="${t.id}" data-ensemble-part="${t.id}"><span class="ensemble-title">${esc(t.name)}</span><span class="ensemble-art">${artwork(getInstrument(t.instrument))}</span><span class="ensemble-pitches" data-now="${t.id}">Ready</span><svg class="note-window" viewBox="0 0 400 72" role="img" aria-label="Upcoming notes for ${esc(t.name)}"><path d="M2 0V72 M100 0V72 M200 0V72 M300 0V72 M399 0V72"/><g data-upcoming="${t.id}"></g></svg><span class="tile-foot">Open this part ↗</span></button>`).join('')}</div>`);
 for(const t of p.tracks){const a=ART[t.instrument],svg=container.querySelector(`[data-ensemble-part="${t.id}"] .ensemble-art svg`);if(!a||!svg)continue;const w=a.width||1536,h=a.height||1024;for(const [slot,shape]of(a.hits||[]).entries()){let el;if(shape.ellipse){el=document.createElementNS('http://www.w3.org/2000/svg','ellipse');['cx','cy','rx','ry'].forEach((k,i)=>el.setAttribute(k,shape.ellipse[i]*(i%2?h:w)))}else if(shape.points){el=document.createElementNS('http://www.w3.org/2000/svg','polygon');el.setAttribute('points',shape.points.map(([x,y])=>x*w+','+y*h).join(' '))}else if(shape.rect){el=document.createElementNS('http://www.w3.org/2000/svg','rect');['x','y','width','height'].forEach((k,i)=>el.setAttribute(k,shape.rect[i]*(i%2?h:w)))}else continue;el.setAttribute('class','ensemble-hit');el.dataset.pitchIndex=shape.noteIndex??slot;svg.append(el)}}
 }
 container.querySelectorAll('[data-console-open]').forEach(el=>el.onclick=()=>open(el.dataset.consoleOpen));
}
// Keep controls consistent when the transport or quick drawer changes the same mix.
export function syncConsoleMix(container,p){
 container.querySelectorAll('input[data-mix-prop]').forEach(el=>{
  const target=el.dataset.mixId==='master'?p:p.tracks.find(t=>t.id===el.dataset.mixId),prop=el.dataset.mixProp;if(!target)return;const value=target[prop]??(prop==='reverbDecay'?2.4:prop==='reverbSend'?1:0);if(+el.value===value)return;
  el.value=value;el.closest('label').querySelector('output').textContent=prop==='pan'?pan(value):prop==='reverbDecay'?value.toFixed(1)+' s':pct(value);if(prop==='pan')syncKnob(el);
 });
 container.querySelectorAll('[data-mix-toggle]').forEach(el=>{const t=p.tracks.find(t=>t.id===el.dataset.mixId);if(t)el.setAttribute('aria-pressed',String(!!t[el.dataset.mixToggle]));});
}
// Event identity always begins with a track, never with a shared pitch range.
export function partActivity(track,beat,playing,key='C'){
 const ns=notesFor(getInstrument(track.instrument),key),active=playing?track.events.filter(e=>e.beat<=beat&&e.beat+Math.max(.18,e.duration)>beat):[];
 return {active,indices:new Set(active.map(e=>ns.findIndex(n=>n.note===e.note&&(n.shift||0)===(e.shift||0)))),upcoming:track.events.filter(e=>e.beat>=beat&&e.beat<beat+4).slice(0,64)};
}
export function updateConsole(container,p,playing,beat,running,audio){
 const audible=new Set(audibleTracks(p).map(t=>t.id));
 container.querySelectorAll('[data-meter]').forEach(el=>{const level=audio.meterLevel(el.dataset.meter),height=level>0?Math.max(0,Math.min(100,(20*Math.log10(level)+60)/60*100)):0;el.firstElementChild.style.height=height+'%';el.style.setProperty('--level',height+'%');el.setAttribute('aria-valuenow',Math.round(height));el.classList.toggle('hot',level>.98)});
 container.querySelectorAll('[data-channel]').forEach(el=>el.classList.toggle('channel-muted',!audible.has(el.dataset.channel)));
 const section=container.querySelector('#ensemble-section');if(!section)return;
 const b=Math.max(0,beat),marker=playing.sectionMarkers?.findLast(m=>m.beat<=b);section.textContent=running?(marker?.name||p.sections?.find(s=>s.id===p.activeSection)?.name||'Playing'):'Ready to play';
 const unit=p.meter==='6/8'?.5:1,beatIndex=Math.floor((b%barBeats(p))/unit);container.querySelector('#ensemble-count').textContent=`Measure ${Math.floor(b/barBeats(p))+1} · Beat ${beatIndex+1}`;container.querySelectorAll('[data-beat-dot]').forEach(el=>el.classList.toggle('on',running&&Number(el.dataset.beatDot)===beatIndex));
 for(const t of p.tracks){const tile=container.querySelector(`[data-ensemble-part="${t.id}"]`);if(!tile)continue;const source=playing.tracks.find(x=>x.id===t.id),state=partActivity(source||{...t,events:[]},b,running&&audible.has(t.id),p.key),inst=getInstrument(t.instrument),ns=notesFor(inst,p.key);
 tile.classList.toggle('sounding',state.active.length>0);tile.classList.toggle('channel-muted',!audible.has(t.id));tile.querySelectorAll('[data-pitch-index]').forEach(el=>el.classList.toggle('lit',state.indices.has(Number(el.dataset.pitchIndex))));
 tile.querySelector('[data-now]').textContent=!audible.has(t.id)?(t.muted?'Muted':'Outside solo'):state.active.length?[...new Set(state.active.map(e=>inst.pads?ns.find(n=>n.note===e.note&&(n.shift||0)===(e.shift||0))?.label||'Hit':noteName(e.note)))].join(' · '):running?'Rest':'Ready';
 const low=Math.min(...ns.map(n=>n.note)),high=Math.max(...ns.map(n=>n.note));tile.querySelector('[data-upcoming]').innerHTML=state.upcoming.map(e=>`<rect x="${2+(e.beat-b)*99}" y="${8+(1-(e.note-low)/Math.max(1,high-low))*45}" width="${Math.max(4,Math.min(e.duration*99,398-(e.beat-b)*99))}" height="7" rx="2"/>`).join('');
 }
}
